{"output": "from collections import Counter, deque


def transform(grid):
    """Retain dense rectangular color panels, filling their marker/noise holes."""
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg] * w for _ in range(h)]
    for color in range(10):
        if color == bg:
            continue
        seen = [[False] * w for _ in range(h)]
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or seen[r][c]:
                    continue
                q = deque([(r, c)])
                seen[r][c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                        if 0 <= yy < h and 0 <= xx < w and not seen[yy][xx] and grid[yy][xx] == color:
                            seen[yy][xx] = True
                            q.append((yy, xx))
                r0, r1 = min(y for y, x in cells), max(y for y, x in cells)
                c0, c1 = min(x for y, x in cells), max(x for y, x in cells)
                area = (r1-r0+1) * (c1-c0+1)
                # Large, near-solid single-color regions are panels; isolated
                # marker cells and sparse decorative noise are discarded.
                if area < 4 or len(cells) < 4 or len(cells) / area < 0.65:
                    continue
                for y in range(r0, r1+1):
                    for x in range(c0, c1+1):
                        out[y][x] = color
    return out


